export interface AuthToken {
  token: string;
  expiresAt: Date;
}

export interface AuthUser {
  id: number;
  username: string;
  email: string;
  role: 'admin' | 'user';
  createdAt: Date;
  authToken?: AuthToken;
}

export class AuthService {
  private users: AuthUser[] = [];
  private tokens: { [token: string]: AuthUser } = {};

  register(username: string, email: string, password: string, role: 'admin' | 'user'): void {
    const user = { id: this.users.length + 1, username, email, role, createdAt: new Date(), authToken: null };
    this.users.push(user);
    this.tokens[user.authToken!] = user;
  }

  login(username: string, password: string): AuthToken | null {
    const user = this.users.find(u => u.username === username && u.authToken);
    if (!user) return null;
    if (user.authToken!.token !== password) return null;
    return user.authToken!;
  }

  logout(token: string): void {
    delete this.tokens[token];
  }

  getUser(token: string): AuthUser | null {
    return this.tokens[token];
  }
}

export interface Message {
  id: number;
  text: string;
  sender: string;
  timestamp: Date;
}

export const messages: Message[] = [];

export function sendMessage(text: string, sender: string): void {
  const newMessage: Message = {
    id: messages.length + 1,
    text,
    sender,
    timestamp: new Date(),
  };
  messages.push(newMessage);
}

export function getMessages(): Message[] {
  return messages;
}

export function removeMessage(id: number): void {
  messages.splice(id - 1, 1);
}

