export function inboundMessages(ws: WebSocket) {
  ws.onmessage = (event) => {
    try {
      const data = JSON.parse(event.data) as { type: 'message'; content: string; sender: string; recipient: string; room: string };

      if (!data || !data.type || !data.content || !data.sender) {
        ws.send(JSON.stringify({ type: 'error', message: 'Invalid message format' }));
        return;
      }

      const user = { id: data.sender, name: data.sender };
      const presence = { user, online: true };

      if (data.type === 'message') {
        const message: { id: string; content: string; sender: string; recipient: string; room: string; timestamp: string } = {
          id: Date.now().toString(),
          content: data.content,
          sender: data.sender,
          recipient: data.recipient,
          room: data.room,
          timestamp: new Date().toISOString(),
        };

        // Store message
        // Send to recipient
        if (data.recipient) {
          const recipientPresence = { user: { id: data.recipient, name: data.recipient }, online: true };
          ws.send(JSON.stringify({ type: 'message', content: message.content, sender: message.sender, recipient: message.recipient, room: message.room }));
        }

        // Send to room
        if (data.room) {
          const roomMembers = [{ id: data.sender, name: data.sender }, { id: data.recipient, name: data.recipient }];
          for (const member of roomMembers) {
            if (member.id !== data.sender && member.id !== data.recipient) {
              ws.send(JSON.stringify({ type: 'message', content: message.content, sender: message.sender, recipient: message.recipient, room: message.room }));
            }
          }
        }
      }
    } catch (err) {
      console.error('Error processing inbound message:', err);
      ws.send(JSON.stringify({ type: 'error', message: 'Failed to process message' }));
    }
  };
}

export function connect_and_send_events(ws: WebSocket) {
  ws.onopen = () => {
    const userId = Math.floor(Math.random() * 1000).toString();
    const user = { id: userId, name: `User ${userId}` };
    const presence = { user, online: true };

    ws.send(JSON.stringify({ type: 'connected', userId }));

    // Send initial messages
    const initialMessages = [
      { id: '1', content: 'Welcome to the chat!', sender: 'system', recipient: null, room: null, timestamp: new Date().toISOString() },
      { id: '2', content: 'This is a sample chat app.', sender: 'system', recipient: null, room: null, timestamp: new Date().toISOString() },
      { id: '3', content: 'Send messages, join rooms, and chat with others!', sender: 'system', recipient: null, room: null, timestamp: new Date().toISOString() },
    ];
    initialMessages.forEach((msg) => {
      ws.send(JSON.stringify({ type: 'message', content: msg.content, sender: msg.sender, recipient: msg.recipient, room: msg.room }));
    });
  };

  ws.onclose = () => {
    const userId = getWebSocketForUser(ws);
    if (userId) {
      const presence = { user: { id: userId, name: `User ${userId}` }, online: false };
      ws.send(JSON.stringify({ type: 'disconnected', userId }));
    }
  };
}

function getWebSocketForUser(ws: WebSocket): string | null {
  const user = { id: '1', name: 'User 1' };
  const presence = { user, online: true };
  return user.id;
}

