export function render(container: HTMLElement) {
  container.innerHTML = `
    <div class="chat-list" style="display:flex;flex-direction:column;gap:10px">
      <div class="chat-list-header" style="display:flex;align-items:center;gap:8px">
        <div style="font-size:0.8rem;color:#888">Chat Rooms</div>
        <button class="btn btn-primary" onclick="openRoomModal()">+ New Room</button>
      </div>
      <div id="chatRoomsList" style="flex:1;overflow-y:auto;max-height:300px"></div>
    </div>
    <div class="chat-panel" style="display:flex;flex-direction:column;gap:10px">
      <div class="chat-panel-header" style="display:flex;align-items:center;gap:8px">
        <div style="font-size:0.8rem;color:#888">Chat Messages</div>
        <div class="chat-users" style="display:flex;gap:4px">
          <div class="chat-user" style="background:#60a5fa;color:#fff;padding:2px 6px;border-radius:3px;font-size:0.6rem">User 1</div>
          <div class="chat-user" style="background:#4ade80;color:#fff;padding:2px 6px;border-radius:3px;font-size:0.6rem">User 2</div>
          <div class="chat-user" style="background:#f87171;color:#fff;padding:2px 6px;border-radius:3px;font-size:0.6rem">User 3</div>
        </div>
      </div>
      <div id="chatMessages" style="flex:1;overflow-y:auto;max-height:400px"></div>
      <div class="chat-input" style="display:flex;gap:8px">
        <input id="chatInput" type="text" placeholder="Type a message..." style="flex:1;padding:6px 12px;background:#1a1a2e;border:1px solid #222;color:#e0e0f0;font-size:0.8rem">
        <button class="btn" onclick="sendMessage()">Send</button>
      </div>
    </div>
  `;

  const chatRoomsList = document.getElementById('chatRoomsList') as HTMLElement;
  const chatMessages = document.getElementById('chatMessages') as HTMLElement;
  const chatInput = document.getElementById('chatInput') as HTMLInputElement;

  const rooms = [
    { id: '1', name: 'Room 1', members: ['user1', 'user2', 'user3'] },
    { id: '2', name: 'Room 2', members: ['user2', 'user3', 'user4'] },
    { id: '3', name: 'Room 3', members: ['user3', 'user4', 'user5'] },
  ];

  const messages = [
    { id: '1', sender: 'user1', text: 'Hello, world!', color: '#00d9ff', fontSize: '0.8rem' },
    { id: '2', sender: 'user2', text: 'What are you up to?', color: '#4ade80', fontSize: '0.8rem' },
    { id: '3', sender: 'user3', text: 'Just coding. How about you?', color: '#f87171', fontSize: '0.8rem' },
  ];

  rooms.forEach(room => {
    const roomEl = document.createElement('div');
    roomEl.className = 'chat-room';
    roomEl.innerHTML = `
      <div class="chat-room-header" style="display:flex;align-items:center;gap:8px">
        <div style="font-size:0.8rem;color:#888">${room.name}</div>
        <div class="chat-users" style="display:flex;gap:4px">
          ${room.members.map(member => `<div class="chat-user" style="background:#60a5fa;color:#fff;padding:2px 6px;border-radius:3px;font-size:0.6rem">${member}</div>`).join('')}
        </div>
      </div>
      <div class="chat-messages" style="max-height:200px;overflow-y:auto;position:relative">
        ${messages.map(msg => `<div class="chat-message" style="color:${msg.color};font-size:${msg.fontSize}">${msg.text}</div>`).join('')}
      </div>
    `;
    chatRoomsList.appendChild(roomEl);
  });

  function sendMessage() {
    const text = chatInput.value.trim();
    if (!text) return;
    chatInput.value = '';
    chatInput.focus();

    messages.push({ id: Date.now().toString(), sender: 'user1', text, color: '#00d9ff', fontSize: '0.8rem' });

    chatMessages.innerHTML = '';
    messages.forEach(msg => {
      const messageEl = document.createElement('div');
      messageEl.className = 'chat-message';
      messageEl.innerHTML = `<div class="chat-message-text" style="color:${msg.color};font-size:${msg.fontSize}">${msg.text}</div>`;
      chatMessages.appendChild(messageEl);
    });

    chatMessages.scrollTop = chatMessages.scrollHeight;
  }

  function openRoomModal() {
    const modal = document.createElement('div');
    modal.className = 'modal';
    modal.innerHTML = `
      <div class="modal-content">
        <span class="close-modal" onclick="closeModal(this)">×</span>
        <div class="modal-title">New Chat Room</div>
        <div class="modal-body">
          <label>Name</label>
          <input id="roomName" type="text" placeholder="Room name">
          <label>Members</label>
          <input id="roomMembers" type="text" placeholder="Comma-separated list of members">
          <button class="btn btn-primary" onclick="createRoom()">Create</button>
        </div>
      </div>
    `;
    document.body.appendChild(modal);
  }

  function closeModal(button: HTMLElement) {
    button.parentElement.remove();
  }

  function createRoom() {
    const name = document.getElementById('roomName') as HTMLInputElement;
    const members = document.getElementById('roomMembers') as HTMLInputElement;
    const room = { id: Date.now().toString(), name: name.value, members: members.value.split(',').map(m => m.trim()) };
    rooms.push(room);
    openRoomModal();
  }
}

